// Stage 5.3.3 — DLP Checker: Active DLP records, milestone notifications
const now = new Date();
const allData = $input.all();

// Parse incoming data
const dlpRecords = [];
const milestones = [];
const projects = [];

for (const item of allData) {
  const d = item.json;
  if (Array.isArray(d)) {
    d.forEach(doc => {
      if (doc.handoverDate) dlpRecords.push(doc);
      else if (doc.projectId && doc.dueDate && doc.status) milestones.push(doc);
      else if (doc.memberIds !== undefined || doc.taskIds !== undefined) projects.push(doc);
      else if (doc.name && doc.status) projects.push(doc);
    });
  }
}

const notifications = [];

// DLP Analysis
dlpRecords.forEach(dlp => {
  const expiryDate = new Date(dlp.dlpExpiry);
  const daysRemaining = Math.ceil((expiryDate - now) / (1000 * 60 * 60 * 24));

  // Alert if DLP expiring within 90 days
  if (daysRemaining > 0 && daysRemaining <= 90) {
    const urgency = daysRemaining <= 30 ? 'critical' : daysRemaining <= 60 ? 'high' : 'warning';
    notifications.push({
      json: {
        type: 'dlp_expiry_warning',
        urgency: urgency,
        projectName: dlp.projectName,
        projectId: dlp.projectId,
        packageCode: dlp.packageCode,
        dlpExpiry: dlp.dlpExpiry,
        daysRemaining: daysRemaining,
        retentionAmount: dlp.retentionAmount,
        openDefects: dlp.openDefects,
        message: `DLP for ${dlp.projectName} (${dlp.packageCode}) expires in ${daysRemaining} days. Retention at stake: ${dlp.retentionAmount}. Open defects: ${dlp.openDefects || 0}.`,
        timestamp: now.toISOString()
      }
    });
  }

  // Alert if DLP has expired and not signed off
  if (daysRemaining <= 0 && dlp.handoverStatus !== 'Completed') {
    notifications.push({
      json: {
        type: 'dlp_expired',
        urgency: 'critical',
        projectName: dlp.projectName,
        projectId: dlp.projectId,
        packageCode: dlp.packageCode,
        dlpExpiry: dlp.dlpExpiry,
        retentionAmount: dlp.retentionAmount,
        message: `DLP for ${dlp.projectName} (${dlp.packageCode}) has EXPIRED. Retention release pending: ${dlp.retentionAmount}.`,
        timestamp: now.toISOString()
      }
    });
  }

  // Alert if open defects near DLP expiry
  if (dlp.openDefects > 0 && daysRemaining > 0 && daysRemaining <= 60) {
    notifications.push({
      json: {
        type: 'dlp_defect_warning',
        urgency: 'high',
        projectName: dlp.projectName,
        projectId: dlp.projectId,
        openDefects: dlp.openDefects,
        closedDefects: dlp.closedDefects,
        message: `${dlp.projectName}: ${dlp.openDefects} open defect(s) with ${daysRemaining} days until DLP expiry. Resolution required before sign-off.`,
        timestamp: now.toISOString()
      }
    });
  }
});

// Milestone Analysis — upcoming due milestones within 14 days
const upcomingMilestones = milestones.filter(m => {
  if (!m.dueDate || m.status === 'completed') return false;
  const due = new Date(m.dueDate);
  const daysUntil = Math.ceil((due - now) / (1000 * 60 * 60 * 24));
  return daysUntil >= 0 && daysUntil <= 14;
});

upcomingMilestones.forEach(m => {
  const due = new Date(m.dueDate);
  const daysUntil = Math.ceil((due - now) / (1000 * 60 * 60 * 24));
  notifications.push({
    json: {
      type: 'milestone_due',
      urgency: daysUntil <= 3 ? 'critical' : 'warning',
      milestoneName: m.name,
      projectId: m.projectId,
      dueDate: m.dueDate,
      daysUntil: daysUntil,
      message: `Milestone '${m.name}' is due in ${daysUntil} day(s) (${m.dueDate}).`,
      timestamp: now.toISOString()
    }
  });
});

if (notifications.length === 0) {
  return [{ json: { status: 'no_issues', message: 'No DLP or milestone alerts this week.', timestamp: now.toISOString() } }];
}

return notifications;

// Write all DLP + milestone notifications to Firestore
const alerts = $input.all();
const results = [];
for (const alert of alerts) {
  results.push({
    json: {
      ...alert.json,
      read: false,
      createdAt: new Date().toISOString(),
      source: 'n8n-dlp-checker'
    }
  });
}
return results;

const data = $input.first().json;
const collection = 'notifications';
const docId = "dlp-" + (data.projectId || data.id || "milestone") + "-" + Date.now();

function toFirestoreValue(val) {
  if (val === null || val === undefined) return { nullValue: null };
  if (typeof val === 'string') return { stringValue: val };
  if (typeof val === 'number') return Number.isInteger(val) ? { integerValue: String(val) } : { doubleValue: val };
  if (typeof val === 'boolean') return { booleanValue: val };
  if (Array.isArray(val)) return { arrayValue: { values: val.map(v => toFirestoreValue(v)) } };
  if (typeof val === 'object') {
    const fields = {};
    for (const [k, v] of Object.entries(val)) fields[k] = toFirestoreValue(v);
    return { mapValue: { fields } };
  }
  return { stringValue: String(val) };
}

const fields = {};
const clean = { ...data };
delete clean._firestoreCollection;
delete clean._firestoreDocId;
for (const [key, val] of Object.entries(clean)) fields[key] = toFirestoreValue(val);

return [{ json: { _firestoreCollection: collection, _firestoreDocId: docId, _firestoreBody: { fields } } }];

